// Spike S10 harness. Sources/S10Core and Sources/S10CoreFFI are generated by ../build.sh.
import Foundation
import PackageDescription

let rustLib = URL(fileURLWithPath: #filePath).deletingLastPathComponent().appendingPathComponent("rust-lib").path

let package = Package(
    name: "s10-harness",
    platforms: [.macOS(.v14)],
    targets: [
        .systemLibrary(name: "S10CoreFFI", path: "Sources/S10CoreFFI"),
        .target(
            name: "S10Core",
            dependencies: ["S10CoreFFI"],
            path: "Sources/S10Core",
            // UniFFI 0.32.2's generated Swift fails Swift 6 strict-concurrency checking (async
            // foreign-trait helpers pass non-Sendable closures to `Task {}`), so the generated
            // module alone is compiled in Swift 5 mode. The harness itself stays in Swift 6 mode.
            swiftSettings: [.swiftLanguageMode(.v5)],
            linkerSettings: [.unsafeFlags(["-L", rustLib])]
        ),
        .executableTarget(
            name: "s10-harness",
            dependencies: ["S10Core"],
            path: "Sources/s10-harness",
            linkerSettings: [
                .linkedFramework("CryptoKit"),
                .linkedFramework("LocalAuthentication"),
                .linkedFramework("Security"),
            ]
        ),
    ]
)
